#include <algorithm>
#include <atomic>
#include <cerrno>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <memory>
#include <thread>
#include <vector>

struct Node {
    Node* left;
    Node* right;
};

class Tree {
    std::unique_ptr<Node[]> nodes_;
    Node* root_;

    static Node* build(Node*& next, unsigned depth) {
        Node* node = next++;
        if (depth == 0) {
            node->left = nullptr;
            node->right = nullptr;
        } else {
            node->left = build(next, depth - 1);
            node->right = build(next, depth - 1);
        }
        return node;
    }

    static std::uint64_t count(const Node* node) {
        if (!node->left) return 1;
        return 1 + count(node->left) + count(node->right);
    }

public:
    explicit Tree(unsigned depth)
        : nodes_(new Node[(std::size_t{1} << (depth + 1)) - 1]) {
        Node* next = nodes_.get();
        root_ = build(next, depth);
    }

    std::uint64_t check() const {
        return count(root_);
    }
};

struct Result {
    unsigned depth;
    std::uint64_t iterations;
    std::uint64_t checksum;
};

int main(int argc, char** argv) {
    if (argc < 2) return 1;

    char* end = nullptr;
    errno = 0;
    const long parsed = std::strtol(argv[1], &end, 10);
    if (errno || end == argv[1] || *end != '\0' || parsed < 0 ||
        parsed >= 63 ||
        parsed + 2 >= std::numeric_limits<std::size_t>::digits) {
        return 1;
    }

    const unsigned n = static_cast<unsigned>(parsed);
    std::ios::sync_with_stdio(false);

    {
        Tree stretch(n + 1);
        std::cout << "stretch tree of depth " << n + 1
                  << "\t check: " << stretch.check() << '\n';
    }

    Tree long_lived(n);

    std::vector<Result> results;
    for (unsigned depth = 4; depth <= n; depth += 2) {
        results.push_back(
            {depth, std::uint64_t{1} << (n - depth + 4), 0});
    }

    if (!results.empty()) {
        std::atomic<std::size_t> next_job{0};

        auto worker = [&]() {
            for (;;) {
                const std::size_t index =
                    next_job.fetch_add(1, std::memory_order_relaxed);
                if (index >= results.size()) return;

                Result& result = results[index];
                std::uint64_t checksum = 0;
                for (std::uint64_t i = 0; i < result.iterations; ++i) {
                    Tree tree(result.depth);
                    checksum += tree.check();
                }
                result.checksum = checksum;
            }
        };

        const unsigned available =
            std::max(1u, std::thread::hardware_concurrency());
        const unsigned workers = std::min(
            {available, 8u, static_cast<unsigned>(results.size())});

        std::vector<std::thread> threads;
        threads.reserve(workers - 1);
        for (unsigned i = 1; i < workers; ++i) {
            threads.emplace_back(worker);
        }
        worker();
        for (auto& thread : threads) thread.join();
    }

    for (const Result& result : results) {
        std::cout << result.iterations << "\t trees of depth "
                  << result.depth << "\t check: "
                  << result.checksum << '\n';
    }

    std::cout << "long lived tree of depth " << n
              << "\t check: " << long_lived.check() << '\n';
    return 0;
}
