    if (n <= 8)
        workers = 1;

    const std::uint64_t chunkSize =
        std::max<std::uint64_t>(1024, total / (workers * 32ULL));
    const std::uint64_t chunkCount =
        (total + chunkSize - 1) / chunkSize;

    std::atomic<std::uint64_t> nextChunk{0};
    std::vector<Result> results(workers);
    std::vector<std::thread> threads;
    threads.reserve(workers - 1);

    auto run = [&](unsigned worker) {
        for (;;) {
            const std::uint64_t chunk =
                nextChunk.fetch_add(1, std::memory_order_relaxed);
            if (chunk >= chunkCount)
                break;

            const std::uint64_t begin = chunk * chunkSize;
            const std::uint64_t end = std::min(total, begin + chunkSize);
            processRange(n, begin, end, factorial, results[worker]);
        }
    };

    for (unsigned i = 1; i < workers; ++i)
        threads.emplace_back(run, i);

    run(0);

    for (auto& thread : threads)
        thread.join();

    std::int64_t checksum = 0;
    int maximum = 0;
    for (const Result& result : results) {
        checksum += result.checksum;
        maximum = std::max(maximum, result.maximum);
    }

    std::cout << checksum << '\n'
              << "Pfannkuchen(" << n << ") = " << maximum << '\n';
    return 0;
}
