    std::array<std::uint64_t, 5> masks{};
    std::array<std::uint64_t, 5> occurrences{};
    for (std::size_t i = 0; i < fragments.size(); ++i) {
        for (unsigned char c : fragments[i])
            patterns[i] = (patterns[i] << 2) | code[c];
        masks[i] = (std::uint64_t{1} << (2 * fragments[i].size())) - 1;
    }

