    std::array<std::uint64_t, 16> pairs{};
    std::uint64_t rolling = 0;
    std::uint64_t length = 0;

    std::string line;
    bool in_three = false;
    while (std::getline(std::cin, line)) {
        if (!line.empty() && line[0] == '>') {
            if (in_three) break;
            if (line.compare(0, 6, ">THREE") == 0 &&
                (line.size() == 6 || line[6] == ' ' ||
                 line[6] == '\t' || line[6] == '\r')) {
                in_three = true;
            }
            continue;
        }
        if (!in_three || (!line.empty() && line[0] == ';')) continue;

        for (unsigned char c : line) {
            const unsigned value = code[c];
            if (value == 255) continue;

            rolling = (rolling << 2) | value;
            ++singles[value];
            if (length != 0) ++pairs[rolling & 15];
            ++length;

            // Every fragment starts with G, whose encoding is nonzero.
            // Thus zero-padded initial windows cannot match prematurely.
            occurrences[0] += ((rolling & masks[0]) == patterns[0]);
            occurrences[1] += ((rolling & masks[1]) == patterns[1]);
            occurrences[2] += ((rolling & masks[2]) == patterns[2]);
            occurrences[3] += ((rolling & masks[3]) == patterns[3]);
            occurrences[4] += ((rolling & masks[4]) == patterns[4]);
        }
    }

    constexpr char bases[] = "ACGT";
    std::cout << std::fixed << std::setprecision(3);

    auto print_frequencies = [&](const auto& counts, unsigned k,
                                 std::uint64_t total) {
        std::array<unsigned, 16> order{};
        const unsigned size = static_cast<unsigned>(counts.size());
        for (unsigned i = 0; i < size; ++i) order[i] = i;

        std::sort(order.begin(), order.begin() + size,
                  [&](unsigned a, unsigned b) {
                      if (counts[a] != counts[b]) return counts[a] > counts[b];
                      return a < b;
                  });

        for (unsigned j = 0; j < size; ++j) {
            const unsigned index = order[j];
            if (counts[index] == 0) continue;

            if (k == 2) std::cout << bases[index >> 2];
            std::cout << bases[index & 3] << ' '
                      << (100.0 * static_cast<double>(counts[index]) /
                          static_cast<double>(total))
                      << '\n';
        }
        std::cout << '\n';
    };

    print_frequencies(singles, 1, length);
    print_frequencies(pairs, 2, length > 0 ? length - 1 : 0);

    for (std::size_t i = 0; i < fragments.size(); ++i)
        std::cout << occurrences[i] << '\t' << fragments[i] << '\n';

    return 0;
}
